const text = ($json.choices && $json.choices[0] && $json.choices[0].message) ? $json.choices[0].message.content : '';

if (!text) {
  throw new Error('Empty response from AI');
}

const clean = text.replace(/```json|```/g, '').trim();
let r;
try {
  r = JSON.parse(clean);
} catch (e) {
  throw new Error('AI returned invalid JSON: ' + clean.slice(0, 200));
}

if (typeof r.overall_score !== 'number' || r.overall_score < 0 || r.overall_score > 100) {
  throw new Error('Invalid overall_score: ' + r.overall_score);
}

// decision and interview_recommended are always derived from the score (same rules as the app)
r.overall_score = Math.round(r.overall_score);
r.decision = r.overall_score >= 75 ? 'strong_match'
           : r.overall_score >= 50 ? 'potential_match'
           : 'not_a_match';
r.interview_recommended = r.overall_score >= 60;

if (!r.decision_reason || typeof r.decision_reason !== 'string') {
  throw new Error('Missing decision_reason');
}

for (const k of ['missing_skills', 'strengths', 'concerns']) {
  if (!Array.isArray(r[k])) r[k] = [];
  r[k] = r[k].map(String);
}

// Safety net: drop any missing_skills entry whose key terms already appear in the CV text
const cv = ($('Webhook').item.json.body.cvText || '').toLowerCase();
const SYNONYMS = [
  ['react', 'react.js', 'reactjs'],
  ['postgres', 'postgresql'],
  ['node', 'node.js', 'nodejs'],
  ['k8s', 'kubernetes'],
  ['next', 'next.js', 'nextjs'],
  ['tailwind', 'tailwindcss', 'tailwind css']
];
const SPLIT_RE = /,|\/|\(|\)|\be\.g\.|\bor\b|\band\b|\bsuch as\b|\bsimilar\b|\bframeworks?\b|\bexperience with\b|\bknowledge of\b|\bexposure to\b|\bbasic\b|\bstrong\b/i;
function escapeRe(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function extractTerms(entry) {
  return String(entry).split(SPLIT_RE)
    .map(s => s.trim().replace(/^[\s\-:;.]+|[\s\-:;.]+$/g, '').toLowerCase())
    .filter(s => s.length >= 2 && s.length <= 40 && /[a-z]/.test(s));
}
function variants(term) {
  const g = SYNONYMS.find(x => x.includes(term));
  return g ? g : [term];
}
function inCv(term) {
  if (/[.+]/.test(term)) return cv.includes(term);
  return new RegExp('(^|[^a-z0-9])' + escapeRe(term) + '([^a-z0-9]|$)').test(cv);
}
const kept = [];
for (const entry of r.missing_skills) {
  const terms = extractTerms(entry);
  const hit = terms.length ? terms.find(t => variants(t).some(inCv)) : null;
  if (hit) {
    console.log('Dropped missing_skills entry (found in CV): "' + entry + '" via term "' + hit + '"');
  } else {
    kept.push(entry);
  }
}
r.missing_skills = kept;

for (const k of ['relevant_experience', 'technical_skills_match', 'education_match']) {
  if (typeof r[k] !== 'string') r[k] = null;
}

return [{ json: r }];
